"""
Quality gate v2: фильтр перед отправкой ордера на Bybit.
"""
from __future__ import annotations

import logging
from typing import Any, Dict, List, Optional, Tuple

from prd_agent.signals.router import UnifiedSignal

logger = logging.getLogger("prd_agent.quality")


class QualityGate:
    def __init__(self, cfg: Dict[str, Any]):
        q = cfg.get("quality_gate", {})
        t = cfg.get("trading", {})
        self.enabled = bool(q.get("enabled", True))
        self.min_confidence = float(
            q.get("min_confidence", t.get("min_signal_confidence", 0.68))
        )
        self.min_rr = float(q.get("min_rr_ratio", 2.5))
        self.require_sl_tp = bool(q.get("require_sl_tp", True))
        self.min_volume = float(
            q.get("min_24h_volume_usdt", t.get("min_24h_volume_usdt", 10_000_000))
        )
        subs = list(q.get("block_meme_symbol_substrings", [])) or list(
            t.get("symbol_blacklist_substrings", [])
        )
        self.meme_subs = tuple(str(x).upper() for x in subs if x)
        self._volume_cache: Dict[str, float] = {}

    async def _symbol_volume(self, exchange, symbol: str) -> float:
        sym = symbol.upper()
        if sym in self._volume_cache:
            return self._volume_cache[sym]
        vol = 0.0
        if hasattr(exchange, "get_tickers"):
            try:
                for t in await exchange.get_tickers():
                    if str(t.get("symbol", "")).upper() == sym:
                        vol = float(t.get("turnover24h", 0) or 0)
                        break
            except Exception as exc:
                logger.warning("quality_gate volume lookup %s: %s", sym, exc)
        self._volume_cache[sym] = vol
        return vol

    @staticmethod
    def _rr_ratio(entry: float, sl: float, tp: float, side: str) -> float:
        if entry <= 0 or sl <= 0 or tp <= 0:
            return 0.0
        is_buy = side.lower() == "buy"
        risk = abs(entry - sl)
        reward = abs(tp - entry) if is_buy else abs(entry - tp)
        if risk <= 0:
            return 0.0
        return reward / risk

    async def check(
        self,
        sig: UnifiedSignal,
        exchange,
        *,
        entry: float,
        sl: float,
        tp: float,
    ) -> Tuple[bool, str]:
        if not self.enabled:
            return True, ""
        sym = sig.symbol.upper()
        if any(part in sym for part in self.meme_subs):
            return False, f"quality_gate: символ {sym} в blacklist (мем/низколиквид)"
        if float(sig.confidence) < self.min_confidence:
            return False, (
                f"quality_gate: confidence {sig.confidence:.2f} < {self.min_confidence:.2f}"
            )
        if self.require_sl_tp and (sl <= 0 or tp <= 0):
            return False, "quality_gate: нет SL/TP"
        rr = self._rr_ratio(entry, sl, tp, sig.side)
        if rr < self.min_rr:
            return False, f"quality_gate: RR {rr:.2f} < {self.min_rr:.2f}"
        vol = await self._symbol_volume(exchange, sym)
        if self.min_volume > 0 and vol > 0 and vol < self.min_volume:
            return False, (
                f"quality_gate: объём 24h {vol:,.0f} < {self.min_volume:,.0f} USDT"
            )
        return True, ""

"""
Агрегация data/trades/trade_history.jsonl для отчётов в Telegram.
"""
from __future__ import annotations

import json
from collections import defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional


def _parse_ts(raw: str) -> Optional[datetime]:
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except (ValueError, TypeError):
        return None


def load_closed_trades(path: Path, hours: float = 24.0) -> List[Dict[str, Any]]:
    if not path.exists():
        return []
    cutoff = datetime.now(timezone.utc) - timedelta(hours=hours)
    out: List[Dict[str, Any]] = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        if row.get("event") != "closed":
            continue
        ts = _parse_ts(str(row.get("ts", "")))
        if ts and ts < cutoff:
            continue
        out.append(row)
    return out


def summarize_trades(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not rows:
        return {"n": 0, "wins": 0, "losses": 0, "winrate": 0.0, "total_pnl": 0.0, "avg_pnl": 0.0}
    pnls = [float(r.get("pnl", 0) or 0) for r in rows]
    wins = sum(1 for p in pnls if p > 0)
    losses = len(pnls) - wins
    total = sum(pnls)
    return {
        "n": len(rows),
        "wins": wins,
        "losses": losses,
        "winrate": wins / len(pnls) * 100 if pnls else 0.0,
        "total_pnl": total,
        "avg_pnl": total / len(pnls) if pnls else 0.0,
    }


def _bucket_stats(rows: List[Dict[str, Any]], key: str, limit: int = 6) -> List[Dict[str, Any]]:
    groups: Dict[str, List[float]] = defaultdict(list)
    for r in rows:
        name = str(r.get(key, "?") or "?")
        groups[name].append(float(r.get("pnl", 0) or 0))
    stats: List[Dict[str, Any]] = []
    for name, pnls in groups.items():
        w = sum(1 for p in pnls if p > 0)
        stats.append(
            {
                "name": name,
                "n": len(pnls),
                "pnl": sum(pnls),
                "winrate": w / len(pnls) * 100 if pnls else 0.0,
            }
        )
    stats.sort(key=lambda x: x["pnl"])
    return stats[:limit]


def format_telegram_report(
    summary: Dict[str, Any],
    *,
    hours: float,
    by_source: List[Dict[str, Any]],
    by_symbol: List[Dict[str, Any]],
    by_reason: List[Dict[str, Any]],
) -> str:
    if summary.get("n", 0) == 0:
        return (
            f"<b>📈 Статистика сделок ({hours:.0f} ч)</b>\n\n"
            "Закрытых сделок в журнале нет.\n"
            "<i>Журнал: data/trades/trade_history.jsonl</i>"
        )
    lines = [
        f"<b>📈 Статистика сделок ({hours:.0f} ч)</b>",
        "",
        f"Сделок: <b>{summary['n']}</b> | Win: {summary['wins']} | Loss: {summary['losses']}",
        f"Winrate: <b>{summary['winrate']:.1f}%</b>",
        f"PnL: <b>{summary['total_pnl']:+.2f}</b> USDT (средн. {summary['avg_pnl']:+.2f})",
        "",
    ]
    if by_reason:
        lines.append("<b>По причине выхода</b>")
        for r in sorted(by_reason, key=lambda x: x["pnl"]):
            lines.append(
                f"• {r['name']}: n={r['n']}, PnL={r['pnl']:+.2f}, WR={r['winrate']:.0f}%"
            )
        lines.append("")
    if by_symbol:
        lines.append("<b>По символам (худшие → лучшие)</b>")
        for r in by_symbol:
            lines.append(
                f"• {r['name']}: n={r['n']}, PnL={r['pnl']:+.2f}, WR={r['winrate']:.0f}%"
            )
        lines.append("")
    if by_source:
        lines.append("<b>По источнику сигнала</b>")
        for r in sorted(by_source, key=lambda x: -x["n"]):
            lines.append(
                f"• {r['name']}: n={r['n']}, PnL={r['pnl']:+.2f}, WR={r['winrate']:.0f}%"
            )
    return "\n".join(lines)


def build_report(journal_path: Path, hours: float = 24.0) -> str:
