from __future__ import annotations

from typing import Any, Dict, List


def normalize_confidence(conf: float) -> float:
    """0..1; значения >1 трактуются как проценты 0..100."""
    c = float(conf or 0)
    if c > 1.0:
        return min(1.0, c / 100.0)
    return max(0.0, c)


