"""Формат AI-Trader для Telegram — понятный русский (как MARKET SCANNER)."""
from __future__ import annotations

import re
from typing import Any

from prd_agent.integrations.ai4trade_ru import (
    _parse_cn_trade,
    _parse_manus_analysis,
    _RE_MANUS_COIN,
    _RE_MANUS_LINE,
    _RE_PUBLISHED,
    _side_ru,
    _translate_cn_fragment,
    _word_ru,
    build_verdict,
    side_ru,
    word_ru,
)

_ACTION_RU = {
    "BUY": "покупка",
    "SELL": "продажа",
    "HOLD": "держать (без входа)",
    "LIGHT_BUY": "лёгкая покупка",
    "LIGHT_SELL": "лёгкая продажа",
    "STRONG_BUY": "сильная покупка",
    "STRONG_SELL": "сильная продажа",
    "LONG": "лонг",
    "SHORT": "шорт",
}

_FOOTER = (
    "──────────────\n"
    "Это информация от AI-Trader — не приказ вашему боту на Bybit открыть сделку."
)


def _action_label(raw: str) -> str:
    key = (raw or "").upper().strip()
    return _ACTION_RU.get(key, _side_ru(raw))


def _manus_coin_blocks(content: str) -> list[dict[str, str]]:
    blocks: list[dict[str, str]] = []
    parts = re.split(r"(?=###?\s*(?:BTC|ETH):)", content, flags=re.I)
    for part in parts:
        m = _RE_MANUS_COIN.search(part)
        if not m:
            continue
        coin = m.group(1).upper()
        action = m.group(2).upper()
        score = m.group(3) or "0"
        row: dict[str, str] = {
            "coin": coin,
            "action": _action_label(action),
            "score": score,
        }
        for lm in _RE_MANUS_LINE.finditer(part):
            key = lm.group(1)
            val = lm.group(2).strip()
            val = re.sub(
                r"\b(NEUTRAL|bullish|bearish|MIXED)\b",
                lambda x: _word_ru(x.group(1)),
                val,
                flags=re.I,
            )
            row[key.lower()] = val
        blocks.append(row)
    return blocks


def _is_manus(content: str, title: str = "") -> bool:
    full = f"{title}\n{content}"
    return "Manus AI" in full or bool(_RE_MANUS_COIN.search(full))


def _is_cn_copy(content: str) -> bool:
    return bool("[Copied from" in content or re.search(r"[\u4e00-\u9fff]", content))


def format_signal_ru(
    signal: dict[str, Any],
    *,
    bases_label: str = "?",
    msg_type: str = "",
) -> str:
    """Плоский русский текст (без HTML) в стиле MARKET SCANNER."""
    content = (signal.get("content") or "").strip()
    title = (signal.get("title") or "").strip()
    agent = str(signal.get("agent_name") or signal.get("leader_name") or "?")
    sym = str(signal.get("symbol") or bases_label).replace("USDT", "")
    typ = word_ru(str(msg_type or signal.get("type") or "signal"))
    side = side_ru(str(signal.get("side") or ""))
    entry = signal.get("entry_price")

    lines: list[str] = ["AI-TRADER", f"Монеты фильтра: {bases_label}"]

    if _RE_PUBLISHED.search(f"{title}\n{content}") or str(msg_type).lower() == "strategy_published":
        lines.extend(
            [
                "Статус: агент опубликовал прогноз в ленте",
                f"Агент: {agent}",
                f"Тип: {typ}",
                f"Заголовок: {title or content[:120]}",
                _FOOTER,
            ]
        )
        return "\n".join(lines)

    if _is_manus(content, title):
        lines.extend(
            [
                "Статус: прогноз Manus AI (чужой AI, демо-счёт)",
                f"Агент: {agent}",
                f"Тип: {typ}",
                f"Вердикт: {build_verdict({**signal, 'type': msg_type})}",
            ]
        )
        for block in _manus_coin_blocks(f"{title}\n{content}"):
            lines.append("")
            lines.append(block["coin"])
            lines.append(f"Рекомендация: {block['action']} (балл {block['score']})")
            if block.get("price"):
                lines.append(f"Цена: {block['price']}")
            if block.get("ta"):
                lines.append(f"Теханализ: {block['ta']}")
            if block.get("news"):
                lines.append(f"Новости: {block['news']}")
            if block.get("macro"):
                lines.append(f"Макро: {block['macro']}")
            if block.get("community"):
                lines.append(f"Сообщество: {block['community']}")

        extras = _parse_manus_analysis(f"{title}\n{content}")
        tail = [e for e in extras if "BTC:" not in e and "ETH:" not in e]
        if tail:
            lines.append("")
            lines.append("Дополнительно: " + " · ".join(tail))
        lines.append(_FOOTER)
        return "\n".join(lines)

    if _is_cn_copy(content):
        lines.extend(
            [
                "Статус: скопированный сигнал другого трейдера",
                f"Агент: {agent}",
                f"Монета: {sym}",
                f"Тип: {typ}",
            ]
        )
        if side:
            action = side
            if "平仓" in content or "减仓" in content:
                action = f"{side} (закрытие / уменьшение позиции)"
            lines.append(f"Действие: {action}")
        if entry is not None:
            lines.append(f"Вход: {entry}")

        cn_lines = _parse_cn_trade(content)
        label_map = {
            "Источник:": "Источник:",
            "Метка:": "Метка:",
            "Сигнал:": "Суть:",
            "Причина:": "Причина:",
        }
        for row in cn_lines:
            if row.startswith("Действие:"):
                continue
            for prefix, out in label_map.items():
                if row.startswith(prefix):
                    lines.append(f"{out} {row[len(prefix):].strip()}")
                    break
            elif " · " in row and ":" in row.split(" · ")[0]:
                lines.append(row.replace(" · ", "\n"))
            else:
                lines.append(row)

        lines.append(f"Вердикт: {build_verdict({**signal, 'type': msg_type})}")
        lines.append(_FOOTER)
        return "\n".join(lines)

    # Простой сигнал
    lines.extend(
        [
            "Статус: торговый сигнал из ленты",
            f"Агент: {agent}",
            f"Монета: {sym}",
            f"Тип: {typ}",
        ]
    )
    if side:
        lines.append(f"Действие: {side}")
    if entry is not None:
        lines.append(f"Вход: {entry}")
    if title:
        lines.append(f"Заголовок: {_translate_cn_fragment(title)}")
    if content and content != title:
        lines.append(f"Текст: {_translate_cn_fragment(content[:300])}")
    lines.append(f"Вердикт: {build_verdict({**signal, 'type': msg_type})}")
    lines.append(_FOOTER)
    return "\n".join(lines)

